def find_equilibrium(stock):
    n = len(stock)
    for i in range(n):
        left_sum = sum(stock[:i])      # Sum of elements before i
        right_sum = sum(stock[i+1:])   # Sum of elements after i
        if left_sum == right_sum:
            return i
    return -1

