def find_equilibrium(stock):
    total_sum = sum(stock)  # Compute total sum once
    left_sum = 0
    for i in range(len(stock)):
        # right_sum = total - left_sum - current element
        right_sum = total_sum - left_sum - stock[i]
        if left_sum == right_sum:
            return i
        left_sum += stock[i]  # Expand left sum to include current element
    return -1

