def min_subarray_len(temps, T):
    n = len(temps)
    min_len = float('inf')
    for i in range(n):
        curr_sum = 0
        for j in range(i, n):
            curr_sum += temps[j]
            if curr_sum >= T:
                min_len = min(min_len, j - i + 1)
                break  # Can't do better starting from i
    return 0 if min_len == float('inf') else min_len

def find_anagram_positions(signal, code):
    result = []
    k = len(code)
    sorted_code = sorted(code)  # Sort code once
    for i in range(len(signal) - k + 1):
        if sorted(signal[i:i+k]) == sorted_code:
            result.append(i)
    return result
